import java.util.*;
import java.io.*;

public class Main {
    static int MOD = 998244353;
    static int base = 3;

    static long power(long a, long n) {
        long res = 1;
        a %= MOD;
        while (n > 0) {
            if ((n & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            n >>= 1;
        }
        return res;
    }

    static void shuffle(long[] arr, int length) {
        for (int i = 1, j = length / 2; i < length - 1; i++) {
            if (i < j) {
                long temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
            int k = length / 2;
            while (j >= k) {
                j -= k;
                k /= 2;
            }
            if (j < k) j += k;
        }
    }

    static void fft(long[] arr, int length, int dir) {
        shuffle(arr, length);
        for (int h = 2; h <= length; h <<= 1) {
            long wlen = power(base, (MOD - 1) / h);
            if (dir == -1) wlen = power(wlen, MOD - 2);
            for (int start = 0; start < length; start += h) {
                long w = 1;
                for (int k = start; k < start + h / 2; k++) {
                    long u = arr[k];
                    long v = arr[k + h / 2] * w % MOD;
                    arr[k] = (u + v) % MOD;
                    arr[k + h / 2] = (u - v + MOD) % MOD;
                    w = w * wlen % MOD;
                }
            }
        }
        if (dir == -1) {
            long inv = power(length, MOD - 2);
            for (int i = 0; i < length; i++) {
                arr[i] = arr[i] * inv % MOD;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int len = 1;
        int halfN = n / 2;
        while (len < (9 * halfN + 1)) len <<= 1;
        long[] arr = new long[len];

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            arr[x] = 1;
        }

        fft(arr, len, 1);

        for (int i = 0; i < len; i++) {
            if (arr[i] != 0) {
                arr[i] = power(arr[i], halfN) % MOD;
            }
        }

        fft(arr, len, -1);

        long totalSum = 0;
        for (int i = 0; i < len; i++) {
            totalSum = (totalSum + arr[i] * arr[i]) % MOD;
        }

        System.out.println(totalSum);
        sc.close();
    }
}
